#include <string>
#include <vector>
#include <map>
#include <sstream>
#include <functional>
#include <memory>
#include <cstring>
#include <openssl/aes.h>
#include <openssl/evp.h>

namespace iot_firmware {

class SecureStorage {
private:
    unsigned char key_[32];
    std::map<std::string, std::string> encrypted_fields_;

    std::string decrypt_field(const std::string& ciphertext) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        unsigned char iv[16] = {0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,
                                 0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f,0x10};
        std::string plaintext(ciphertext.size() + 16, '\0');
        int len = 0, plaintext_len = 0;
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key_, iv);
        EVP_DecryptUpdate(ctx, (unsigned char*)&plaintext[0], &len,
                         (unsigned char*)ciphertext.data(), ciphertext.size());
        plaintext_len = len;
        EVP_DecryptFinal_ex(ctx, (unsigned char*)&plaintext[0] + len, &len);
        plaintext_len += len;
        plaintext.resize(plaintext_len);
        EVP_CIPHER_CTX_free(ctx);
        return plaintext;
    }

public:
    SecureStorage(const unsigned char* master_key) {
        memcpy(key_, master_key, 32);
    }

    void store(const std::string& key, const std::string& encrypted_val) {
        encrypted_fields_[key] = encrypted_val;
    }

    std::string retrieve(const std::string& key) {
        auto it = encrypted_fields_.find(key);
        if (it == encrypted_fields_.end()) return "";
        return decrypt_field(it->second);
    }
};

class GraphQLFieldResolver {
private:
    SecureStorage& storage_;

    std::string normalize_identifier(const std::string& input) {
        std::string result;
        result.reserve(input.size());
        for (size_t i = 0; i < input.size(); i++) {
            char c = input[i];
            if (c == '\\' && i + 1 < input.size()) {
                char next = input[i + 1];
                if (next == 'u' && i + 5 < input.size()) {
                    std::string hex = input.substr(i + 2, 4);
                    unsigned int codepoint = std::stoul(hex, nullptr, 16);
                    if (codepoint < 0x80) {
                        result += static_cast<char>(codepoint);
                    }
                    i += 5;
                } else {
                    result += next;
                    i++;
                }
            } else {
                result += c;
            }
        }
        return result;
    }

    bool is_safe_field_name(const std::string& raw_field) {
        for (char c : raw_field) {
            if (c == '{' || c == '}' || c == '(' || c == ')' ||
                c == '\n' || c == '\r' || c == ';') {
                return false;
            }
        }
        if (raw_field.find("__") == 0) return false;
        return true;
    }

public:
    GraphQLFieldResolver(SecureStorage& storage) : storage_(storage) {}

    std::string resolve_query(const std::string& query_template,
                              const std::map<std::string, std::string>& variables) {
        std::string resolved = query_template;
        for (auto& [var_name, var_value] : variables) {
            std::string placeholder = "$" + var_name;
            size_t pos;
            while ((pos = resolved.find(placeholder)) != std::string::npos) {
                std::string normalized = normalize_identifier(var_value);
                if (is_safe_field_name(var_value)) {
                    resolved.replace(pos, placeholder.size(), normalized);
                } else {
                    resolved.replace(pos, placeholder.size(), "_blocked_");
                }
            }
        }
        return resolved;
    }

    std::string execute_device_query(const std::string& field_name) {
        std::string query = "{ device { $field } }";
        std::map<std::string, std::string> vars = {{"field", field_name}};
        std::string final_query = resolve_query(query, vars);

        if (final_query.find("secret") != std::string::npos ||
            final_query.find("key") != std::string::npos) {
            return "{\"error\": \"access denied\"}";
        }

        return execute_on_engine(final_query);
    }

    std::string execute_on_engine(const std::string& query) {
        if (query.find("firmware_version") != std::string::npos) {
            return "{\"data\": {\"device\": {\"firmware_version\": \"2.1.4\"}}}";
        }
        if (query.find("master_key") != std::string::npos) {
            return "{\"data\": {\"device\": {\"master_key\": \"" + storage_.retrieve("master_key") + "\"}}}";
        }
        if (query.find("config") != std::string::npos) {
            return "{\"data\": {\"device\": {\"config\": \"" + storage_.retrieve("config") + "\"}}}";
        }
        return "{\"data\": null}";
    }
};

} // namespace iot_firmware

int main() {
    unsigned char key[32] = {0};
    iot_firmware::SecureStorage storage(key);
    storage.store("master_key", "encrypted_master_key_data");
    storage.store("config", "encrypted_config_data");

    iot_firmware::GraphQLFieldResolver resolver(storage);

    // Normal usage
    auto result = resolver.execute_device_query("firmware_version");
    return 0;
}
